{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "int.Parse returns 32-bit int; must use long.Parse for int64 field in new schema"
    },
    "C002": {
      "decision": "unaffected",
      "reason": "entity.Quantity.ToString() returns canonical decimal string for int64; behavior unchanged"
    },
    "C003": {
      "decision": "unaffected",
      "reason": "entity.Quantity > 0 preserves strict >0 stock predicate; int64 comparison unchanged"
    },
    "C004": {
      "decision": "unaffected",
      "reason": "record definition unchanged; request.Quantity remains string input for canonical decimal parsing"
    }
  },
  "edits": [
    {
      "before": "            var sample = new Simulation.Inventory.StockItem { Sku = request.Sku, Quantity = int.Parse(request.Quantity, CultureInfo.InvariantCulture) };\n",
      "after": "            var sample = new Simulation.Inventory.StockItem { Sku = request.Sku, Quantity = long.Parse(request.Quantity, CultureInfo.InvariantCulture) };\n"
    }
  ],
  "rationale": "Schema change from int32 to int64 requires updating parsing from int.Parse to long.Parse to correctly handle int64 values. The output string representation via ToString() and the stock predicate remain valid for int64. No changes needed to Dictionary output or return statement.",
  "confidence": 0.95,
  "assumptions": [
    "Request.Quantity contains valid canonical decimal string representation of a signed 64-bit integer",
    "Consumers will migrate before any out-of-int32 range producers are active",
    "ts-proto generated code will properly handle int64 as string per forceLong=string configuration"
  ]
}
